"""Build dashboard assets and reuse PlatformIO's normal uploader for parallel USB uploads."""
Import("env")
import importlib.util
import json
from pathlib import Path
import subprocess
import sys
from SCons.Script import DefaultEnvironment

project_dir = Path(env.subst("$PROJECT_DIR"))
subprocess.run(["node", str(project_dir / "usermods/inter_comms_ui/build_ui.mjs")], cwd=project_dir, check=True)


def load_module(name, path):
    """Load the project's filesystem helper or the SDK's authoritative partition parser."""
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def runtime_config_path(env):
    """Locate the SDK configuration actually selected for this target and memory type."""
    board = env.BoardConfig()
    framework = Path(env.PioPlatform().get_package_dir("framework-arduinoespressif32"))
    return (framework / "tools/esp32-arduino-libs" / board.get("build.mcu") /
            board.get("build.arduino.memory_type", "qio_qspi") / "include/sdkconfig.h")


def normal_upload_arguments(env, firmware):
    """Resolve current SDK upload flags on every invocation, including cached builds."""
    arguments = []
    for flag in env.get("UPLOADERFLAGS", []):
        raw = str(flag)
        arguments.append("@PORT@" if "$UPLOAD_PORT" in raw else env.subst(raw).strip('"'))
    if "write-flash" not in arguments or "@PORT@" not in arguments:
        raise ValueError("Parallel flashing requires PlatformIO's normal serial esptool uploader")
    arguments.extend([env.subst("$ESP32_APP_OFFSET"), str(firmware)])
    return arguments


def build_upload_inputs(source, target, env):
    """Generate a model image and capture the exact normal-upload arguments after SDK setup."""
    framework = Path(env.PioPlatform().get_package_dir("framework-arduinoespressif32"))
    parser = load_module("upload_partitions", framework / "tools/gen_esp32part.py")
    helper = load_module("model_filesystem", project_dir / "usermods/inter_comms_ui/factory_image.py")
    build_dir = Path(env.subst("$BUILD_DIR")).resolve()
    table = parser.PartitionTable.from_binary((build_dir / "partitions.bin").read_bytes())
    table.verify()
    partition = table.find_by_name("spiffs")
    if partition is None or partition.type != parser.DATA_TYPE or partition.subtype != 0x82:
        raise ValueError("A LittleFS model partition is required")
    config = helper.read_runtime_config(runtime_config_path(env))
    package = project_dir / "build_output/inter-comms-assets"
    model_image = build_dir / "model-filesystem.bin"
    model_image.write_bytes(helper.build_filesystem(package, partition.size, config))
    firmware = build_dir / (env.subst("${PROGNAME}") + ".bin")
    arguments = normal_upload_arguments(env, firmware)
    plan = {"uploader": env.subst("$UPLOADER").strip('"'), "arguments": arguments,
            "firmware": str(firmware), "modelPackage": str(package),
            "helper": str(project_dir / "usermods/inter_comms_ui/factory_image.py"),
            "filesystem": {"offset": partition.offset, "size": partition.size,
                           "image": str(model_image), "config": config}}
    (build_dir / "parallel-upload.json").write_text(json.dumps(plan, indent=2), encoding="utf-8")


def upload_all(source, target, env):
    """Run normal firmware upload plus USB model verification/repair on each selected port."""
    plan = Path(env.subst("$BUILD_DIR")) / "parallel-upload.json"
    current = json.loads(plan.read_text(encoding="utf-8"))
    current["arguments"] = normal_upload_arguments(env, current["firmware"])
    current["uploader"] = env.subst("$UPLOADER").strip('"')
    plan.write_text(json.dumps(current, indent=2), encoding="utf-8")
    command = [sys.executable, str(project_dir / "tools/flash_all.py"), "--plan", str(plan)]
    ports = env.subst("$UPLOAD_PORT")
    if ports:
        command.extend(["--ports", ports])
    subprocess.run(command, cwd=project_dir, check=True)


project_env = DefaultEnvironment()
build_dir = Path(project_env.subst("$BUILD_DIR"))
assets_dir = project_dir / "build_output/inter-comms-assets"
inputs = project_env.Command(
    [str(build_dir / "model-filesystem.bin"), str(build_dir / "parallel-upload.json")],
    [str(build_dir / (project_env.subst("${PROGNAME}") + ".bin")), str(build_dir / "partitions.bin"),
     str(assets_dir / "manifest.json"), str(project_dir / "usermods/inter_comms_ui/factory_image.py"),
     str(project_dir / "usermods/inter_comms_ui/build.py"), str(runtime_config_path(project_env))] +
    [str(path) for path in sorted((assets_dir / "inter_comms").glob("*.webp"))],
    project_env.VerboseAction(build_upload_inputs, "Preparing normal-upload plan and model verification image"),
)
project_env.Alias("buildprog", inputs)
for name in ("uploadall", "uploadfactory"):
    project_env.AddCustomTarget(name, inputs,
        project_env.VerboseAction(upload_all, "Uploading all USB boards; checking/repairing model images"),
        title="Upload all USB boards" if name == "uploadall" else "Upload all USB boards and check images",
        description="Normal firmware upload in parallel, then verify model files and repair only if needed")
